// 有効なRSS情報源のみ抽出
console.log($("RSS情報源管理シート読み取り").all());
const validRssFeeds = $("RSS情報源管理シート読み取り").all().filter(item => 
  item.json["有効/無効"] === '有効'
).map(item => ({
  category: item.json.カテゴリ,
  source_name: item.json.情報源名,
  rss_url: item.json["RSS URL"],
  priority: item.json.優先度 || 1
}));

return validRssFeeds;

// 1日以内の記事のみ抽出
const oneDayAgo = new Date();
oneDayAgo.setDate(oneDayAgo.getDate() - 30);
const recentArticles = items.filter(item => {
  const pubDate = new Date(item.json.pubDate || item.json.isoDate);
  return pubDate >= oneDayAgo;
});
console.log(`全記事: ${items.length}, 1日以内: ${recentArticles.length} (${$input.first().json.source_name})`);

return recentArticles;

// RSS記事データを統一フォーマットに整形
const sourceInfo = $("Loop Over Items").first().json;

return items.map(item => ({
  title: item.json.title,
  description: item.json.description || item.json.summary || item.json.contentSnippet,
  link: item.json.link,
  pubDate: item.json.pubDate || item.json.isoDate,
  category: sourceInfo.category,
  source_name: sourceInfo.source_name,
  priority: sourceInfo.priority,
  collected_at: new Date().toISOString(),
  processed: false,
  guid: item.json.guid || item.json.link  // 重複判定用
}));

// 全ての記事を取得して言語判定
const articles = $input.all();

const englishArticles = [];
const japaneseArticles = [];

articles.forEach(item => {
  const title = item.json.title || '';
  const description = item.json.description || '';
  const text = (title + ' ' + description);

  // 日本語文字（ひらがな、カタカナ、漢字）の存在をチェック
  const hasJapanese = /[\u3040-\u309F\u30A0-\u30FF\u4E00-\u9FAF]/.test(text);

  if (hasJapanese) {
    // 日本語記事
    japaneseArticles.push({
      ...item.json,
      needsTranslation: false
    });
  } else {
    // 英語記事（翻訳が必要）
    englishArticles.push({
      ...item.json,
      needsTranslation: true
    });
  }
});

console.log(`総記事数: ${articles.length}`);
console.log(`英語記事: ${englishArticles.length} (翻訳対象)`);
console.log(`日本語記事: ${japaneseArticles.length} (翻訳不要)`);

// 全記事を統合して返す（翻訳フラグ付き）
return [...englishArticles, ...japaneseArticles];

// 入力データから記事情報を取得（制限: 最大15件）
const allArticles = $input.all();
const maxArticles = 15; // Slack APIの50ブロック制限に対応
const articles = allArticles.slice(0, maxArticles);

// ヘッダーブロック
const blocks = [
  {
    "type": "header",
    "text": {
      "type": "plain_text",
      "text": `📰 AI・N8N情報収集結果 (${articles.length}/${allArticles.length}件)`,
      "emoji": true
    }
  },
  {
    "type": "context",
    "elements": [
      {
        "type": "mrkdwn",
        "text": `📅 ${new Date().toLocaleString('ja-JP')} | 🤖 自動収集システム`
      }
    ]
  },
  {
    "type": "divider"
  }
];

// 各記事のセクションブロックを生成
articles.forEach((article, index) => {
  // 記事内容を制限（セクションブロックの文字数制限に対応）
  const maxContentLength = 150; // さらに短縮
  const content = article.json.記事内容 || '';
  const truncatedContent = content.length > maxContentLength 
    ? content.substring(0, maxContentLength) + '...' 
    : content;

  // タイトルも制限
  const maxTitleLength = 80;
  const title = article.json.元記事タイトル || '';
  const truncatedTitle = title.length > maxTitleLength 
    ? title.substring(0, maxTitleLength) + '...' 
    : title;

  // 記事セクション（メタデータと統合）
  blocks.push({
    "type": "section",
    "text": {
      "type": "mrkdwn",
      "text": `*${index + 1}. ${truncatedTitle}*\n${truncatedContent}\n\n_📅 ${article.json.日付} | 🏷️ ${article.json.カテゴリ || 'AI関連'}_`
    },
    "accessory": {
      "type": "button",
      "text": {
        "type": "plain_text",
        "text": "記事を読む",
        "emoji": true
      },
      "url": article.json.元記事URL,
      "action_id": `read_article_${index}`
    }
  });

  // 記事間の区切り（最後の記事以外）
  if (index < articles.length - 1) {
    blocks.push({
      "type": "divider"
    });
  }
});

// 件数が制限を超えている場合の注意書き
if (allArticles.length > maxArticles) {
  blocks.push({
    "type": "context",
    "elements": [
      {
        "type": "mrkdwn",
        "text": `⚠️ 全${allArticles.length}件中、上位${maxArticles}件のみ表示しています。`
      }
    ]
  });
}

// メッセージサイズチェック（概算）
const messageSize = JSON.stringify({ blocks }).length;
console.log(`メッセージサイズ: ${messageSize} bytes / 16KB制限`);

// 16KB制限チェック（安全マージン含む）
if (messageSize > 14000) { // 14KBで警告
  console.warn('メッセージサイズが大きすぎます。記事数をさらに減らすことを推奨します。');
}

return { blocks };

