// シンプルで確実なJSON解析関数
function parseAiJson(jsonString) {
  try {
    // まず普通にパースを試行
    return JSON.parse(jsonString);
  } catch (error) {
    // 失敗したら改行文字のみクリーニングしてリトライ
    const cleaned = jsonString.replace(/[\r\n\t]/g, ' ').replace(/\s+/g, ' ');
    return JSON.parse(cleaned);
  }
}

// JSON内で問題となる文字をエスケープする関数
function escapeForJson(str) {
  if (typeof str !== 'string') return str;
  return str
    .replace(/\\/g, '\\\\')  // バックスラッシュ
    .replace(/"/g, '\\"')    // 二重引用符
    .replace(/\n/g, '\\n')   // 改行
    .replace(/\r/g, '\\r')   // キャリッジリターン
    .replace(/\t/g, '\\t');  // タブ
}

// メイン処理
const processedItems = [];

for (const item of items) {
  try {
    const aiResponse = item.json.choices[0].message.content;
    const parsedData = parseAiJson(aiResponse);

    processedItems.push({
      json: {
        X: escapeForJson(parsedData.X || ""),
        Facebook: escapeForJson(parsedData.Facebook || ""),
        Threads: escapeForJson(parsedData.Threads || "")
      }
    });
  } catch (error) {
    processedItems.push({
      json: {
        X: "エラー",
        Facebook: "エラー", 
        Threads: "エラー",
        errorDetails: error.message
      }
    });
  }
}

return processedItems;
